text:
Laboratorio: operadores booleanos en vivo


Laboratorio · datos en vivo de OpenAlex

Escribe dos conceptos (puedes usar OR, comillas y truncamiento dentro de cada uno) y pulsa Buscar. El libro consulta OpenAlex, un índice abierto con más de 250 millones de trabajos académicos, y te muestra cuántos documentos recupera cada combinación. Observa cómo AND reduce, OR amplía y NOT excluye.

viewof consulta = {
  const f = html`&lt;form class="lab-form"&gt;
    &lt;div class="row g-2"&gt;
      &lt;div class="col-md-5"&gt;&lt;label class="form-label" for="lab-a"&gt;Concepto A&lt;/label&gt;
        &lt;input id="lab-a" name="a" class="form-control form-control-sm" value='smartphone OR "mobile phone"'&gt;&lt;/div&gt;
      &lt;div class="col-md-5"&gt;&lt;label class="form-label" for="lab-b"&gt;Concepto B&lt;/label&gt;
        &lt;input id="lab-b" name="b" class="form-control form-control-sm" value='"academic performance"'&gt;&lt;/div&gt;
      &lt;div class="col-md-2 d-flex align-items-end"&gt;&lt;button class="btn btn-primary btn-sm w-100" type="submit"&gt;Buscar&lt;/button&gt;&lt;/div&gt;
    &lt;/div&gt;&lt;/form&gt;`;
  f.value = {a: f.a.value, b: f.b.value};
  f.onsubmit = e =&gt; { e.preventDefault(); f.value = {a: f.a.value.trim(), b: f.b.value.trim()}; f.dispatchEvent(new Event("input", {bubbles: true})); };
  return f;
}







recuentos = {
  const q = s =&gt; fetch("https://api.openalex.org/works?per-page=1&search=" + encodeURIComponent(s))
    .then(r =&gt; { if (!r.ok) throw new Error(r.status); return r.json(); }).then(j =&gt; j.meta.count);
  const A = `(${consulta.a})`, B = `(${consulta.b})`;
  yield {cargando: true};
  try {
    const [a, b, y, o, n] = await Promise.all([q(A), q(B), q(`${A} AND ${B}`), q(`${A} OR ${B}`), q(`${A} NOT ${B}`)]);
    yield {a, b, y, o, n};
  } catch (e) { yield {error: true}; }
}







{
  if (recuentos.cargando) return html`&lt;p role="status"&gt;Consultando OpenAlex…&lt;/p&gt;`;
  if (recuentos.error) return html`&lt;p role="status"&gt;No se ha podido consultar OpenAlex (¿estás sin conexión?). Prueba más tarde.&lt;/p&gt;`;
  const filas = [["A", recuentos.a], ["B", recuentos.b], ["A AND B", recuentos.y], ["A OR B", recuentos.o], ["A NOT B", recuentos.n]];
  const max = Math.max(...filas.map(f =&gt; f[1]), 1);
  const fmt = new Intl.NumberFormat("es-ES");
  return html`&lt;table class="table table-sm lab-tabla" role="status"&gt;
    &lt;caption&gt;Documentos en OpenAlex para cada combinación&lt;/caption&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th scope="col"&gt;Búsqueda&lt;/th&gt;&lt;th scope="col"&gt;Documentos&lt;/th&gt;&lt;th scope="col"&gt;&lt;span class="visually-hidden"&gt;Barra&lt;/span&gt;&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;${filas.map(([k, v]) =&gt; html`&lt;tr&gt;&lt;th scope="row"&gt;&lt;code&gt;${k}&lt;/code&gt;&lt;/th&gt;&lt;td style="text-align:right"&gt;${fmt.format(v)}&lt;/td&gt;
      &lt;td style="width:50%"&gt;&lt;div style="height:.8rem;border-radius:2px;background:#2a78d6;width:${Math.max(1, 100 * v / max)}%"&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;&lt;/table&gt;
    &lt;p&gt;Comprueba: &lt;code&gt;A OR B&lt;/code&gt; = &lt;code&gt;A&lt;/code&gt; + &lt;code&gt;B&lt;/code&gt; − &lt;code&gt;A AND B&lt;/code&gt;
    (${fmt.format(recuentos.a + recuentos.b - recuentos.y)} frente a ${fmt.format(recuentos.o)}; la diferencia se debe al motor de búsqueda).&lt;/p&gt;`;
}






Prueba: añade un sinónimo a A con OR y mira cómo cambia A AND B; después, pon una frase entre comillas y compárala con las mismas palabras sin comillas.

Laboratorio: así ve un detector de coincidencias


Laboratorio · se ejecuta en tu navegador, sin enviar el texto a ningún sitio

Pega un texto original y tu versión. El laboratorio divide los dos en grupos de tres palabras (trigramas), calcula qué proporción comparten (similitud de Jaccard) y resalta en tu versión las palabras que forman parte de trigramas copiados. Prueba con una copia literal, una escritura en mosaico y una paráfrasis de verdad.

texto = window.Lab.texto
area = window.Lab.area
seleccion = window.Lab.seleccion
rango = window.Lab.rango
boton = window.Lab.boton





































viewof original = area("Texto original", {rows: 4, value: "La lectura lateral consiste en salir de la página para comprobar qué dicen otras fuentes sobre ella y sobre lo que afirma."})
viewof version = area("Tu versión", {rows: 4, value: "La lectura lateral consiste en salir de la web para comprobar lo que dicen otras fuentes sobre ella y sobre lo que afirma."})
















{
  const palabras = t =&gt; t.toLowerCase().normalize("NFC").replace(/[^\p{L}\p{N}\s]/gu, " ").split(/\s+/).filter(Boolean);
  const tri = p =&gt; { const s = new Set(); for (let i = 0; i + 2 &lt; p.length; i++) s.add(p.slice(i, i + 3).join(" ")); return s; };
  const pa = palabras(original), pb = palabras(version), ta = tri(pa), tb = tri(pb);
  const comunes = [...tb].filter(x =&gt; ta.has(x));
  const union = new Set([...ta, ...tb]);
  const j = union.size ? comunes.length / union.size : 0;
  const marcadas = new Array(pb.length).fill(false);
  for (let i = 0; i + 2 &lt; pb.length; i++) if (ta.has(pb.slice(i, i + 3).join(" "))) { marcadas[i] = marcadas[i + 1] = marcadas[i + 2] = true; }
  const veredicto = j &gt;= 0.8 ? "casi una copia literal" : j &gt;= 0.25 ? "muchas coincidencias: posible escritura en mosaico" : j &gt; 0 ? "pocas coincidencias" : "sin coincidencias de tres palabras";
  return html`&lt;div role="status"&gt;
    &lt;p&gt;&lt;strong&gt;Similitud: ${(100 * j).toFixed(0)} %&lt;/strong&gt; (${comunes.length} trigramas compartidos de ${union.size} distintos) · ${veredicto}.&lt;/p&gt;
    ${(() =&gt; { const p = document.createElement("p"); p.className = "lab-resaltado"; pb.forEach((w, i) =&gt; { if (i) p.append(" "); if (marcadas[i]) { const m = document.createElement("mark"); m.textContent = w; p.append(m); } else p.append(w); }); return p; })()}
    &lt;p class="small"&gt;Recuerda: una similitud baja &lt;em&gt;no&lt;/em&gt; prueba que no haya plagio (una paráfrasis o una traducción sin cita lo son), y una alta tampoco lo prueba si el fragmento está citado.&lt;/p&gt;&lt;/div&gt;`;
}

Laboratorio: del DOI a la referencia


Laboratorio · datos en vivo de Crossref

Escribe un DOI y el laboratorio pide a Crossref la referencia en APA 7, igual que hace un gestor bibliográfico. Después, revísala: busca mayúsculas de más, cursivas que faltan o datos incompletos. Es exactamente lo que encontraron Gilmour y Cobus-Kuo (2011).

texto = window.Lab.texto
area = window.Lab.area
seleccion = window.Lab.seleccion
rango = window.Lab.rango
boton = window.Lab.boton





































viewof doi = texto("DOI", {value: "10.1016/j.pragma.2013.07.012", submit: "Obtener la referencia"})







referencia = {
  const limpio = doi.trim().replace(/^https?:\/\/(dx\.)?doi\.org\//i, "").replace(/^doi:\s*/i, "");
  if (!/^10\.\d{4,9}\/\S+$/.test(limpio)) { yield {aviso: "Eso no parece un DOI: empiezan por «10.» seguido de un prefijo y una barra."}; return; }
  yield {cargando: true};
  try {
    const r = await fetch(`https://api.crossref.org/v1/works/${encodeURIComponent(limpio)}/transform`, {headers: {Accept: "text/x-bibliography; style=apa"}});
    if (r.status === 404) { yield {aviso: "Crossref no conoce ese DOI. Puede ser de otra agencia (DataCite, por ejemplo) o no existir: compruébalo en https://doi.org/" + limpio}; return; }
    yield {texto: (await r.text()).trim(), doi: limpio};
  } catch (e) { yield {aviso: "No se ha podido consultar Crossref (¿estás sin conexión?)."}; }
}







referencia.cargando ? html`&lt;p role="status"&gt;Consultando Crossref…&lt;/p&gt;` :
referencia.aviso ? html`&lt;p role="status"&gt;${referencia.aviso}&lt;/p&gt;` :
html`&lt;div role="status"&gt;&lt;p&gt;&lt;strong&gt;Referencia generada:&lt;/strong&gt;&lt;/p&gt;&lt;blockquote class="lab-cita"&gt;${referencia.texto}&lt;/blockquote&gt;
&lt;p class="small"&gt;¿Qué corregirías? En APA, el título del artículo va en minúscula salvo la primera palabra y los nombres propios, y la revista y el volumen van en cursiva (aquí se pierde el formato).&lt;/p&gt;&lt;/div&gt;`






Prueba también: 10.1108/eb024320, 10.1038/s41598-023-41032-5 o el DOI de este libro, 10.5281/zenodo.24515144 (de DataCite, no de Crossref).

Laboratorio: un modelo de lenguaje en miniatura


Laboratorio · se ejecuta en tu navegador

Este modelo de juguete ha «leído» solo una docena de frases sobre bibliotecas e información. Para cada palabra cuenta qué palabras la siguen y con qué frecuencia (un modelo de bigramas). Elige una palabra de inicio y la temperatura: con temperatura baja elige casi siempre la palabra más probable; con temperatura alta, se arriesga más. Genera varias frases: verás textos fluidos y plausibles, algunos de ellos falsos. Los grandes modelos son muchísimo más complejos, pero comparten esta idea: predecir lo siguiente, no comprobar la verdad.

texto = window.Lab.texto
area = window.Lab.area
seleccion = window.Lab.seleccion
rango = window.Lab.rango
boton = window.Lab.boton





































corpus = `la biblioteca ofrece libros y revistas a los estudiantes .
la biblioteca ofrece acceso a bases de datos científicas .
los estudiantes buscan artículos en bases de datos .
los estudiantes citan los artículos con su referencia .
la referencia incluye el autor y el año del artículo .
el autor del artículo publica en una revista científica .
una revista científica revisa los artículos por pares .
los artículos revisados ofrecen información fiable .
la información fiable cita sus fuentes .
la desinformación imita la información fiable .
los estudiantes verifican la información en varias fuentes .
el catálogo de la biblioteca ofrece libros y artículos .`
modelo = {
  const m = new Map();
  for (const f of corpus.split("\n")) {
    const p = f.trim().split(/\s+/);
    for (let i = 0; i + 1 &lt; p.length; i++) {
      if (!m.has(p[i])) m.set(p[i], new Map());
      const s = m.get(p[i]); s.set(p[i + 1], (s.get(p[i + 1]) || 0) + 1);
    }
  }
  return m;
}
viewof inicio = seleccion("Palabra de inicio", [...modelo.keys()].filter(w =&gt; w !== ".").sort((a, b) =&gt; a.localeCompare(b, "es")), {value: "los"})
viewof temperatura = rango("Temperatura", [0.1, 2], {step: 0.1, value: 1})
viewof generar = boton("Generar otra frase")





































probs = (w, t) =&gt; {
  const s = modelo.get(w); if (!s) return [];
  const pares = [...s.entries()], pesos = pares.map(([, c]) =&gt; Math.pow(c, 1 / t)), z = pesos.reduce((a, b) =&gt; a + b, 0);
  return pares.map(([p], i) =&gt; [p, pesos[i] / z]).sort((a, b) =&gt; b[1] - a[1]);
}
frase = {
  generar;
  const out = [inicio]; let w = inicio;
  for (let k = 0; k &lt; 18 && w !== "."; k++) {
    const ps = probs(w, temperatura); if (!ps.length) break;
    let r = Math.random(), acc = 0, elegido = ps[ps.length - 1][0];
    for (const [p, q] of ps) { acc += q; if (r &lt;= acc) { elegido = p; break; } }
    out.push(elegido); w = elegido;
  }
  return out.join(" ").replace(" .", ".");
}
html`&lt;div role="status"&gt;&lt;p&gt;&lt;strong&gt;Frase generada:&lt;/strong&gt; «${frase}»&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Qué puede seguir a «${inicio}»&lt;/strong&gt; con temperatura ${temperatura}:&lt;/p&gt;
&lt;table class="table table-sm"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th scope="col"&gt;Siguiente palabra&lt;/th&gt;&lt;th scope="col"&gt;Probabilidad&lt;/th&gt;&lt;th scope="col"&gt;&lt;span class="visually-hidden"&gt;Barra&lt;/span&gt;&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
${probs(inicio, temperatura).slice(0, 6).map(([p, q]) =&gt; html`&lt;tr&gt;&lt;td&gt;${p}&lt;/td&gt;&lt;td&gt;${(100 * q).toFixed(0)} %&lt;/td&gt;&lt;td style="width:50%"&gt;&lt;div style="height:.8rem;border-radius:2px;background:#2a78d6;width:${100 * q}%"&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;`)}
&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;`






















Prueba: genera frases desde «la» con temperatura 2. ¿Alguna afirma algo que el corpus no dice? Eso es, a pequeña escala, una alucinación.

Laboratorio: verificar referencias


Laboratorio · datos en vivo de doi.org y Crossref

Pega los DOI que te ha dado una IA (uno por línea; también vale el enlace completo). El laboratorio comprueba en doi.org si cada DOI existe y, si es de Crossref, trae el título y el año para que compruebes que coinciden con lo que te dijo la IA.

viewof lista = area("DOI (uno por línea)", {rows: 5, submit: "Verificar",
  value: "10.1038/s41598-023-41032-5\n10.1016/j.ipm.2019.102041\n10.1093/jis/abc123\nhttps://doi.org/10.1145/3442188.3445922"})







verificacion = {
  const dois = lista.split(/\n+/).map(x =&gt; x.trim().replace(/^https?:\/\/(dx\.)?doi\.org\//i, "").replace(/^doi:\s*/i, "")).filter(Boolean).slice(0, 20);
  yield {cargando: true};
  const uno = async d =&gt; {
    if (!/^10\.\d{4,9}\/\S+$/.test(d)) return {d, estado: "formato", texto: "No tiene formato de DOI."};
    try {
      const h = await (await fetch("https://doi.org/api/handles/" + encodeURI(d))).json();
      if (h.responseCode !== 1) return {d, estado: "no", texto: "No existe en doi.org."};
      try {
        const r = await fetch("https://api.crossref.org/works/" + encodeURIComponent(d));
        if (r.ok) { const m = (await r.json()).message;
          const anio = (m.issued?.["date-parts"]?.[0]?.[0]) ?? "s. f.";
          return {d, estado: "si", texto: `${(m.title || [""])[0]} (${anio}). ${(m["container-title"] || [""])[0]}`}; }
      } catch (e) {}
      return {d, estado: "si", texto: "Existe (registrado fuera de Crossref, por ejemplo en DataCite)."};
    } catch (e) { return {d, estado: "error", texto: "No se ha podido consultar (¿sin conexión?)."}; }
  };
  yield {filas: await Promise.all(dois.map(uno))};
}







verificacion.cargando ? html`&lt;p role="status"&gt;Verificando…&lt;/p&gt;` : html`&lt;table class="table table-sm" role="status"&gt;
&lt;caption&gt;${verificacion.filas.filter(f =&gt; f.estado === "si").length} de ${verificacion.filas.length} DOI existen&lt;/caption&gt;
&lt;thead&gt;&lt;tr&gt;&lt;th scope="col"&gt;DOI&lt;/th&gt;&lt;th scope="col"&gt;¿Existe?&lt;/th&gt;&lt;th scope="col"&gt;Lo que dice el registro&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
${verificacion.filas.map(f =&gt; html`&lt;tr&gt;&lt;td&gt;&lt;code&gt;${f.d}&lt;/code&gt;&lt;/td&gt;&lt;td&gt;${f.estado === "si" ? "✓ Sí" : f.estado === "no" ? "✗ No" : "?"}&lt;/td&gt;&lt;td&gt;${f.texto}&lt;/td&gt;&lt;/tr&gt;`)}
&lt;/tbody&gt;&lt;/table&gt;`






Un DOI que existe no basta: comprueba que el título, los autores y el año coinciden con la referencia que te dio la IA. Walters y Wilder (2023) encontraron, además de referencias inventadas, muchas referencias reales con errores en sus datos.

Laboratorio: evalúa una fuente con el test CRAAP


Laboratorio · se ejecuta en tu navegador

El test CRAAP, creado en la Meriam Library de la California State University, Chico, evalúa una fuente con cinco criterios. Puntúa una fuente que estés usando (de 0 a 10) y mira su perfil.

rangoC = window.Lab.rango
viewof cActualidad = rangoC("Actualidad: ¿es reciente para tu tema? ¿se actualiza?", [0, 10], {value: 7})
viewof cRelevancia = rangoC("Relevancia: ¿responde a tu pregunta y al nivel adecuado?", [0, 10], {value: 8})
viewof cAutoridad = rangoC("Autoridad: ¿quién lo firma? ¿tiene credenciales y afiliación?", [0, 10], {value: 4})
viewof cExactitud = rangoC("Exactitud: ¿aporta pruebas y fuentes verificables? ¿ha sido revisada?", [0, 10], {value: 3})
viewof cProposito = rangoC("Propósito: ¿informa, vende, persuade o entretiene?", [0, 10], {value: 5})












































{
  const crit = [["Actualidad", cActualidad], ["Relevancia", cRelevancia], ["Autoridad", cAutoridad], ["Exactitud", cExactitud], ["Propósito", cProposito]];
  const total = crit.reduce((s, c) =&gt; s + c[1], 0);
  const peor = [...crit].sort((a, b) =&gt; a[1] - b[1])[0];
  const barras = crit.map(([n, v], i) =&gt; `&lt;g transform="translate(0 ${i * 34})"&gt;&lt;text x="0" y="20" font-size="14" fill="currentColor"&gt;${n}&lt;/text&gt;&lt;rect x="110" y="6" width="300" height="20" rx="4" fill="var(--bs-secondary-bg)"/&gt;&lt;rect x="110" y="6" width="${v * 30}" height="20" rx="4" fill="${v &lt; 5 ? "#b3261e" : "#1c6b3a"}"/&gt;&lt;text x="${118 + v * 30}" y="21" font-size="13" fill="currentColor"&gt;${v}${v &lt; 5 ? " ⚠" : ""}&lt;/text&gt;&lt;/g&gt;`).join("");
  const veredicto = total &gt;= 40 && peor[1] &gt;= 5 ? "Fuente sólida: puedes usarla, citándola correctamente." : total &gt;= 25 ? `Úsala con cautela y contrástala con otras fuentes. Su punto débil es la ${peor[0].toLowerCase()}.` : "Fuente poco fiable: busca otra mejor antes de usarla.";
  const d = html`&lt;div role="status" aria-live="polite"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;svg viewBox="0 0 460 172" width="100%" style="max-width:520px" role="img" aria-label="Perfil CRAAP: ${crit.map(([n, v]) =&gt; n + " " + v).join(", ")}" font-family="inherit"&gt;${barras}&lt;/svg&gt;&lt;p&gt;&lt;strong&gt;Total: ${total} de 50.&lt;/strong&gt; ${veredicto}&lt;/p&gt;${peor[0] === "Exactitud" || peor[0] === "Autoridad" ? '&lt;p class="small"&gt;Pista: aplica la &lt;strong&gt;lectura lateral&lt;/strong&gt; (abre otras pestañas y busca qué dicen otros sobre la fuente) antes de seguir leyendo.&lt;/p&gt;' : ""}`;
  return d;
}






Los criterios con menos de 5 se marcan con ⚠. Una puntuación alta no sustituye al juicio crítico: el test es una guía, no una fórmula.
